// Original NOIR diagrams inspired by Tinycharts' playable-diagram concept.
// No Tinycharts templates, skill code, illustrations, or paid assets are included.
const base=`.diagram{width:min(95%,510px);font:11px/1.45 system-ui,sans-serif;color:#ddd}.diagram *{box-sizing:border-box}.diagram-header{display:flex;justify-content:space-between;gap:10px;align-items:center;margin-bottom:10px}.diagram-header strong{font-size:12px;font-weight:500}.diagram-header span{font-size:9px;color:#999}.diagram svg{display:block;width:100%;height:146px;overflow:visible}.diagram svg text{font:9px system-ui,sans-serif;fill:#aaa}.diagram .node rect{fill:#171717;stroke:#626262;stroke-width:1.1}.diagram .node text{text-anchor:middle;dominant-baseline:middle;fill:#bbb}.diagram .node.active rect,.diagram .node.done rect{fill:#ddd;stroke:#eee}.diagram .node.active text,.diagram .node.done text{fill:#161616}.diagram .edge{fill:none;stroke:#555;stroke-width:1.3}.diagram .edge.active{stroke:#ddd;stroke-width:2}.diagram .controls{display:flex;justify-content:center;gap:6px;flex-wrap:wrap;align-items:center;margin-top:12px}.diagram button,.diagram input{font:inherit}.diagram button{cursor:pointer;padding:6px 9px;min-height:28px;background:#202020;border:1px solid #444;border-radius:5px;color:#ddd}.diagram button.primary{background:#ddd;border-color:#ddd;color:#111}.diagram button:disabled{opacity:.35;cursor:default}.diagram button:focus-visible,.diagram input:focus-visible,.diagram summary:focus-visible{outline:2px solid #ddd;outline-offset:3px}.diagram input{accent-color:#ddd}.diagram .status{text-align:center;color:#999;font-size:10px;margin:10px 0 0;min-height:15px}.diagram .rules{margin-top:11px;padding-top:8px;border-top:1px solid #303030;font-size:9px;color:#888}.diagram .rules summary{cursor:pointer;width:max-content}.diagram .rules p{margin:7px 0 0;max-width:450px;line-height:1.6}.diagram .options{display:flex;justify-content:center;gap:12px;flex-wrap:wrap;margin:5px 0 9px;color:#aaa;font-size:9px}.diagram .options label{display:flex;align-items:center;gap:4px}@media(prefers-reduced-motion:reduce){.diagram *{animation:none!important;transition:none!important}}`;
const source={name:'Tinycharts · April Zhu',url:'https://april-zhu.com/tinycharts',note:'Original NOIR state and diagram implementation inspired by the playable-chart concept; no Tinycharts code or assets imported.'};
const make=(id,name,description,html,css,js)=>({id,name,category:'diagrams',description,tags:['Interactive','Diagram','Tinycharts'],isNew:true,inspiration:source,html,css:base+css,js});
const arrow=`<defs><marker id="arrow" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0 0 6 3 0 6" fill="none" stroke="#aaa"/></marker></defs>`;
const node=(id,x,y,w,label)=>`<g class="node" data-node="${id}"><rect x="${x}" y="${y}" width="${w}" height="30" rx="6"/><text x="${x+w/2}" y="${y+15}">${label}</text></g>`;
const rules=text=>`<details class="rules"><summary>Show the rules</summary><p>${text}</p></details>`;
export default [
make('ref-order-sequence','Order sequence','Step through a delivery sequence across four participants. Every message follows the order state.',
`<div class="diagram"><header class="diagram-header"><strong>One order, four participants</strong><span id="sequence-count">0 / 5 messages</span></header><svg viewBox="0 0 440 166" role="img" aria-label="Order delivery sequence diagram">${arrow}${[45,162,277,395].map((x,i)=>`<text x="${x}" y="10" text-anchor="middle">${['Customer','App','Kitchen','Courier'][i]}</text><path d="M${x} 23v138" stroke="#444" stroke-dasharray="3 4"/>`).join('')}${[[45,162,37,'Place order'],[162,277,63,'Accept order'],[277,162,89,'Ready for pickup'],[277,395,115,'Collect parcel'],[395,45,147,'Deliver order']].map((r,i)=>`<g class="sequence-message" data-message="${i}"><path d="M${r[0]} ${r[2]}H${r[1]}" stroke="#ddd" stroke-width="1.3" marker-end="url(#arrow)"/><text x="${(r[0]+r[1])/2}" y="${r[2]-6}" text-anchor="middle">${r[3]}</text></g>`).join('')}</svg><div class="controls"><button id="sequence-prev" disabled>Previous</button><button class="primary" id="sequence-next">Next message</button><button id="sequence-reset">Reset</button></div><p class="status" id="sequence-status" role="status">Waiting for an order.</p>${rules('Messages advance in a fixed sequence: placed → accepted → ready → collected → delivered. Previous and Reset move only within that sequence.')}</div>`,
`.sequence-message{opacity:.12;transition:opacity .2s}.sequence-message.visible{opacity:.5}.sequence-message.current{opacity:1}.sequence-message.current text{fill:#eee;font-weight:500}`,
`let step=0;const states=['Waiting for an order.','Order placed with the app.','Kitchen accepted the order.','Order is ready for pickup.','Courier collected the parcel.','Delivered to the customer.'];function render(){document.querySelector('#sequence-count').textContent=step+' / 5 messages';document.querySelector('#sequence-status').textContent=states[step];document.querySelector('#sequence-prev').disabled=step===0;document.querySelector('#sequence-next').disabled=step===5;document.querySelectorAll('[data-message]').forEach((g,i)=>{g.classList.toggle('visible',i<step);g.classList.toggle('current',i===step-1)})}document.querySelector('#sequence-next').onclick=()=>{step=Math.min(5,step+1);render()};document.querySelector('#sequence-prev').onclick=()=>{step=Math.max(0,step-1);render()};document.querySelector('#sequence-reset').onclick=()=>{step=0;render()};render();`),
make('ref-refund-flow','Refund decision flow','A branching decision diagram with explicit eligibility rules, review state, and approved or declined outcomes.',
`<div class="diagram"><header class="diagram-header"><strong>Refund review</strong><span id="refund-state">Not submitted</span></header><div class="options"><label><input type="checkbox" id="refund-window" checked> Within 30 days</label><label><input type="checkbox" id="refund-sealed" checked> Item unopened</label></div><svg viewBox="0 0 430 142" role="img" aria-label="Refund request decision flow">${arrow}<path class="edge" data-edge="review" d="M112 40h69" marker-end="url(#arrow)"/><path class="edge" data-edge="approved" d="M254 40h24v-17h38" marker-end="url(#arrow)"/><path class="edge" data-edge="declined" d="M218 55v55h98" marker-end="url(#arrow)"/>${node('request',20,25,92,'Request')}${node('review',181,25,73,'Review')}${node('approved',317,8,94,'Approved')}${node('declined',317,95,94,'Declined')}<text x="278" y="15">eligible</text><text x="243" y="103">not eligible</text></svg><div class="controls"><button class="primary" id="refund-next">Submit request</button><button id="refund-reset">Reset</button></div><p class="status" id="refund-status" role="status">Choose the conditions, then submit.</p>${rules('A request must be reviewed before a decision. It is approved only if both conditions are true. Conditions lock after submission; Reset starts a new request.')}</div>`,
`.diagram .options input:disabled{opacity:.5}`,
`let stage='request';const within=document.querySelector('#refund-window'),sealed=document.querySelector('#refund-sealed'),next=document.querySelector('#refund-next');function render(){document.querySelectorAll('[data-node]').forEach(n=>n.classList.toggle('active',n.dataset.node===stage));document.querySelectorAll('[data-edge]').forEach(e=>e.classList.toggle('active',e.dataset.edge===stage));within.disabled=sealed.disabled=stage!=='request';next.disabled=stage==='approved'||stage==='declined';next.textContent=stage==='request'?'Submit request':'Make decision';document.querySelector('#refund-state').textContent={request:'Not submitted',review:'Under review',approved:'Approved',declined:'Declined'}[stage];document.querySelector('#refund-status').textContent={request:'Choose the conditions, then submit.',review:'Review checks both eligibility conditions.',approved:'Both conditions passed. Refund approved.',declined:'At least one condition failed. Refund declined.'}[stage]}next.onclick=()=>{if(stage==='request')stage='review';else if(stage==='review')stage=within.checked&&sealed.checked?'approved':'declined';render()};document.querySelector('#refund-reset').onclick=()=>{stage='request';render()};render();`),
make('ref-playable-statechart','Playable statechart','A small job state machine where Start, Pause, Resume, and Finish are available only in valid states.',
`<div class="diagram"><header class="diagram-header"><strong>Job lifecycle</strong><span id="job-state">Idle</span></header><svg viewBox="0 0 440 140" role="img" aria-label="Job lifecycle statechart">${arrow}<path class="edge" d="M104 48h40M244 48h60" marker-end="url(#arrow)"/><path class="edge" d="M204 63v39M145 117h-20V80h40V63" marker-end="url(#arrow)"/>${node('idle',24,33,80,'Idle')}${node('running',144,33,100,'Running')}${node('complete',304,33,105,'Complete')}${node('paused',145,102,100,'Paused')}<text x="112" y="36">start</text><text x="256" y="36">finish</text><text x="199" y="88">pause / resume</text></svg><div class="controls"><button class="primary" data-event="start">Start</button><button data-event="pause" disabled>Pause</button><button data-event="resume" disabled>Resume</button><button data-event="finish" disabled>Finish</button><button data-event="reset">Reset</button></div><p class="status" id="job-log" role="status">Idle. Start a job to begin.</p>${rules('Idle accepts Start. Running accepts Pause or Finish. Paused accepts Resume. Complete accepts Reset. Reset is also available from every other state.')}</div>`,
`.diagram [data-event]{font-size:10px}`,
`const transitions={idle:{start:'running'},running:{pause:'paused',finish:'complete'},paused:{resume:'running'},complete:{}};let state='idle';function render(event){document.querySelector('#job-state').textContent=state[0].toUpperCase()+state.slice(1);document.querySelectorAll('[data-node]').forEach(n=>n.classList.toggle('active',n.dataset.node===state));document.querySelectorAll('[data-event]').forEach(b=>b.disabled=b.dataset.event!=='reset'&&!transitions[state][b.dataset.event]);document.querySelector('#job-log').textContent=event?'Event: '+event+' → '+state: 'Idle. Start a job to begin.'}document.querySelectorAll('[data-event]').forEach(b=>b.onclick=()=>{const event=b.dataset.event;if(event==='reset')state='idle';else if(transitions[state][event])state=transitions[state][event];render(event)});render();`),
make('ref-allocation-flow','Allocation flow','Adjust a conserved flow between spending, savings, and fees. Branch widths and values always agree.',
`<div class="diagram"><header class="diagram-header"><strong>Monthly allocation</strong><span>Illustrative units</span></header><svg viewBox="0 0 440 150" role="img" aria-label="Allocation flow with conserved total"><path id="flow-spend" d="M85 76C200 76 200 30 331 30" stroke="#d5d5d5" fill="none" stroke-width="24"/><path id="flow-save" d="M85 76C200 76 200 83 331 83" stroke="#999" fill="none" stroke-width="16"/><path d="M85 76C200 76 200 132 331 132" stroke="#555" fill="none" stroke-width="4"/><rect x="34" y="48" width="54" height="56" rx="5" fill="#222" stroke="#aaa"/><text x="61" y="70" text-anchor="middle">100</text><text x="61" y="86" text-anchor="middle">units</text><text x="344" y="27">Spend</text><text id="spend-amount" x="344" y="41">60</text><text x="344" y="80">Save</text><text id="save-amount" x="344" y="94">35</text><text x="344" y="129">Fees</text><text x="344" y="143">5</text></svg><div class="controls"><label class="allocation-control">Savings <input id="allocation-range" type="range" min="0" max="95" value="35" aria-label="Savings allocation"><output id="allocation-output">35%</output></label></div><p class="status" id="allocation-status" role="status">60 spend + 35 save + 5 fees = 100</p>${rules('The total is fixed at 100 units. Fees always take 5. Changing savings reallocates the remaining 95 between spending and savings; no branch can become negative.')}</div>`,
`.allocation-control{display:flex;align-items:center;gap:12px;color:#aaa;font-size:10px}.allocation-control input{width:170px}.allocation-control output{width:32px}.diagram #spend-amount,.diagram #save-amount{font-size:12px;fill:#ddd}`,
`const input=document.querySelector('#allocation-range');function render(){const save=Number(input.value),spend=95-save;document.querySelector('#spend-amount').textContent=String(spend);document.querySelector('#save-amount').textContent=String(save);document.querySelector('#flow-spend').setAttribute('stroke-width',Math.max(.5,spend*.45));document.querySelector('#flow-spend').style.opacity=spend?'1':'0';document.querySelector('#flow-save').setAttribute('stroke-width',Math.max(.5,save*.45));document.querySelector('#flow-save').style.opacity=save?'1':'0';document.querySelector('#allocation-output').textContent=save+'%';document.querySelector('#allocation-status').textContent=spend+' spend + '+save+' save + 5 fees = 100'}input.oninput=render;render();`),
make('ref-queue-simulator','Queue simulator','Step a queue through three workers, watch jobs complete, and inspect a deterministic processing model.',
`<div class="diagram"><header class="diagram-header"><strong>Three-worker queue</strong><span id="queue-summary">0 completed</span></header><div class="queue-tray" id="queue-tray" aria-label="Waiting jobs">Queue is empty</div><svg class="queue-links" viewBox="0 0 420 30" aria-hidden="true"><path d="M210 0v12H65v18M210 12v18M210 12h145v18" fill="none" stroke="#555" stroke-width="1.2"/></svg><div class="workers">${[0,1,2].map(i=>`<div class="worker"><span>Worker ${i+1}</span><strong id="worker-${i}">Idle</strong><div class="worker-progress"><i id="worker-progress-${i}"></i></div></div>`).join('')}</div><div class="controls"><button id="queue-add">Add job</button><button class="primary" id="queue-tick" disabled>Advance tick</button><button id="queue-reset">Reset</button></div><p class="status" id="queue-status" role="status">Add jobs, then advance the clock.</p>${rules('Each job needs two processing ticks. On each tick, active jobs progress first; then idle workers take the next queued job. At most 12 jobs may wait. Nothing advances without a tick.')}</div>`,
`.queue-tray{display:flex;align-items:center;justify-content:center;gap:5px;min-height:36px;background:#131313;border:1px dashed #444;border-radius:6px;padding:7px;color:#777;font-size:10px;flex-wrap:wrap}.queue-tray span{padding:2px 5px;background:#ddd;border-radius:3px;color:#111;font-size:8px}.diagram svg.queue-links{height:26px}.workers{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.worker{padding:11px;background:#181818;border:1px solid #444;border-radius:6px;text-align:center}.worker>span{display:block;color:#888;font-size:9px}.worker strong{display:block;font-size:11px;font-weight:400;margin:7px 0}.worker-progress{height:3px;background:#363636;overflow:hidden}.worker-progress i{height:100%;display:block;background:#ddd;width:0}`,
`let next=1,queue=[],workers=[null,null,null],completed=0,ticks=0;function render(){document.querySelector('#queue-summary').textContent=completed+' completed';document.querySelector('#queue-tray').innerHTML=queue.length?queue.map(id=>'<span>#'+id+'</span>').join(''):'Queue is empty';workers.forEach((job,i)=>{document.querySelector('#worker-'+i).textContent=job?'Job #'+job.id:'Idle';document.querySelector('#worker-progress-'+i).style.width=job?(2-job.remaining)*50+'%':'0%'});document.querySelector('#queue-add').disabled=queue.length>=12;document.querySelector('#queue-tick').disabled=!queue.length&&!workers.some(Boolean);document.querySelector('#queue-status').textContent=ticks?'Tick '+ticks+' / '+queue.length+' waiting / '+workers.filter(Boolean).length+' processing':'Add jobs, then advance the clock.'}document.querySelector('#queue-add').onclick=()=>{if(queue.length<12)queue.push(next++);render()};document.querySelector('#queue-tick').onclick=()=>{ticks++;workers=workers.map(job=>{if(!job)return null;job.remaining--;if(job.remaining===0){completed++;return null}return job});workers=workers.map(job=>job|| (queue.length?{id:queue.shift(),remaining:2}:null));render()};document.querySelector('#queue-reset').onclick=()=>{next=1;queue=[];workers=[null,null,null];completed=ticks=0;render()};render();`),
make('ref-dependency-pipeline','Dependency pipeline','Run a small build graph in dependency order. Locked steps become available when their prerequisites finish.',
`<div class="diagram"><header class="diagram-header"><strong>Build dependencies</strong><span id="pipeline-count">0 / 5 complete</span></header><svg viewBox="0 0 440 145" role="img" aria-label="Build dependency graph">${arrow}<path class="edge" d="M89 72h23V33h24M112 72v39h24M208 33h22v39h24M208 111h22V72M327 72h23" marker-end="url(#arrow)"/>${node('source',15,57,74,'Source')}${node('lint',136,18,72,'Lint')}${node('test',136,96,72,'Tests')}${node('bundle',254,57,73,'Bundle')}${node('release',350,57,75,'Release')}</svg><div class="controls pipeline-controls">${['source','lint','test','bundle','release'].map(id=>`<button data-run="${id}" ${id!=='source'?'disabled':''}>${id[0].toUpperCase()+id.slice(1)}</button>`).join('')}</div><div class="controls"><button class="primary" id="pipeline-ready">Run ready steps</button><button id="pipeline-reset">Reset</button></div><p class="status" id="pipeline-status" role="status">Source is ready to run.</p>${rules('Lint and Tests both require Source. Bundle requires both Lint and Tests. Release requires Bundle. Run ready steps takes one snapshot of the currently available work, so dependent steps wait for the next click.')}</div>`,
`.pipeline-controls{margin-top:0!important}.pipeline-controls button{padding:4px 7px;min-height:24px;font-size:9px}.diagram .node.ready rect{stroke:#ddd;stroke-dasharray:3 2}`,
`const dependencies={source:[],lint:['source'],test:['source'],bundle:['lint','test'],release:['bundle']};const done=new Set();const ready=id=>!done.has(id)&&dependencies[id].every(x=>done.has(x));function render(){const available=Object.keys(dependencies).filter(ready);document.querySelectorAll('[data-node]').forEach(n=>{n.classList.toggle('done',done.has(n.dataset.node));n.classList.toggle('ready',ready(n.dataset.node))});document.querySelectorAll('[data-run]').forEach(b=>{b.disabled=!ready(b.dataset.run);b.textContent=(done.has(b.dataset.run)?'✓ ':'')+b.dataset.run});document.querySelector('#pipeline-count').textContent=done.size+' / 5 complete';document.querySelector('#pipeline-ready').disabled=!available.length;document.querySelector('#pipeline-status').textContent=available.length?'Ready: '+available.join(', '):'Release complete. Reset to run the graph again.'}document.querySelectorAll('[data-run]').forEach(b=>b.onclick=()=>{if(ready(b.dataset.run))done.add(b.dataset.run);render()});document.querySelector('#pipeline-ready').onclick=()=>{const available=Object.keys(dependencies).filter(ready);available.forEach(x=>done.add(x));render()};document.querySelector('#pipeline-reset').onclick=()=>{done.clear();render()};render();`)
];
